"""MiniLang exception hierarchy."""

class MiniLangError(Exception):
    """Base exception for all MiniLang errors."""
    def __init__(self, message: str, position: int | None = None) -> None:
        super().__init__(message)
        self.message = message
        self.position = position

    def __str__(self) -> str:
        return self.message


class LexError(MiniLangError):
    """Raised when tokenization fails."""
    pass


class ParseError(MiniLangError):
    """Raised when parsing fails."""
    pass


class EvalError(MiniLangError):
    """Raised when evaluation fails."""
    pass

"""MiniLang lexical analyzer."""

from .errors import LexError


class Token:
    """A lexical token."""
    __slots__ = ("kind", "value", "position")

    def __init__(self, kind: str, value: object, position: int) -> None:
        self.kind = kind
        self.value = value
        self.position = position

    def __repr__(self) -> str:
        return f"Token({self.kind}, {self.value!r}, {self.position})"

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Token):
            return (self.kind, self.value, self.position) == (other.kind, other.value, other.position)
        return False


KEYWORDS = {"true", "false", "and", "or", "not"}


def tokenize(source: str) -> list[Token]:
    """Tokenize the input source code into a list of tokens."""
    tokens: list[Token] = []
    i = 0
    n = len(source)

    while i < n:
        ch = source[i]

        # 1. Whitespace
        if ch in " \t\r\n":
            i += 1
            continue

        # 2. Comments
        if ch == "#":
            i += 1
            while i < n and source[i] != "\n":
                i += 1
            continue

        # 4. Strings
        if ch == '"':
            start = i
            i += 1
            chars: list[str] = []
            terminated = False
            while i < n:
                c = source[i]
                if c in "\r\n":
                    raise LexError("literal newline in string", position=i)
                elif c == '"':
                    i += 1
                    terminated = True
                    break
                elif c == "\\":
                    esc_pos = i
                    i += 1
                    if i >= n:
                        raise LexError("unterminated string escape", position=esc_pos)
                    esc_char = source[i]
                    if esc_char == "n":
                        chars.append("\n")
                    elif esc_char == "t":
                        chars.append("\t")
                    elif esc_char == "r":
                        chars.append("\r")
                    elif esc_char == '"':
                        chars.append('"')
                    elif esc_char == "\\":
                        chars.append("\\")
                    else:
                        raise LexError(f"invalid escape sequence: \\{esc_char}", position=esc_pos)
                    i += 1
                else:
                    chars.append(c)
                    i += 1

            if not terminated:
                raise LexError("unterminated string", position=start)

            tokens.append(Token("STRING", "".join(chars), start))
            continue

        # 5 & 6. Identifiers and Keywords
        if ch.isalpha() or ch == "_":
            start = i
            while i < n and (source[i].isalnum() or source[i] == "_"):
                i += 1
            word = source[start:i]
            if word in KEYWORDS:
                tokens.append(Token("KEYWORD", word, start))
            else:
                tokens.append(Token("IDENT", word, start))
            continue

        # 3. Numbers: 123, 1.5, .5, 1e3, 1.2e-4, 2E+8. A number may not end with '.'
        if ch.isdigit() or (ch == "." and i + 1 < n and source[i + 1].isdigit()):
            start = i
            if ch == ".":
                i += 1
                while i < n and source[i].isdigit():
                    i += 1
            else:
                while i < n and source[i].isdigit():
                    i += 1
                if i < n and source[i] == ".":
                    dot_pos = i
                    if i + 1 < n and source[i + 1].isdigit():
                        i += 1
                        while i < n and source[i].isdigit():
                            i += 1
                    else:
                        raise LexError("number may not end with '.'", position=dot_pos)

            # Optional exponent
            if i < n and source[i] in "eE":
                exp_pos = i
                exp_i = i + 1
                if exp_i < n and source[exp_i] in "+-":
                    exp_i += 1
                if exp_i >= n or not source[exp_i].isdigit():
                    raise LexError("invalid exponent in number literal", position=exp_pos)
                while exp_i < n and source[exp_i].isdigit():
                    exp_i += 1
                i = exp_i

            # Check trailing identifier chars
            if i < n and (source[i].isalpha() or source[i] == "_"):
                raise LexError(f"invalid character in number literal: {source[i]!r}", position=i)

            num_str = source[start:i]
            try:
                num_val = float(num_str)
            except ValueError:
                raise LexError(f"invalid number: {num_str!r}", position=start)
            tokens.append(Token("NUMBER", num_val, start))
            continue

        # 7. Operators and punctuation
        if source[i : i + 2] in ("==", "!=", "<=", ">="):
            tokens.append(Token("OP", source[i : i + 2], i))
            i += 2
            continue

        if ch == "=":
            raise LexError("unexpected '='", position=i)

        if ch == "!":
            raise LexError("unexpected '!'", position=i)

        if ch in "+-*/%^<>()" or ch == ",":
            tokens.append(Token("OP", ch, i))
            i += 1
            continue

        # 8. Any other character
        raise LexError(f"unexpected character: {ch!r}", position=i)

    return tokens

"""MiniLang parser and AST definitions."""

from dataclasses import dataclass
from typing import Any
from .errors import ParseError
from .lexer import Token, tokenize


@dataclass
class Literal:
    value: Any
    position: int


@dataclass
class Variable:
    name: str
    position: int


@dataclass
class UnaryOp:
    op: str
    operand: Any
    position: int


@dataclass
class BinaryOp:
    op: str
    left: Any
    right: Any
    position: int


@dataclass
class FunctionCall:
    name: str
    args: list[Any]
    position: int


class Parser:
    """Recursive-descent parser for MiniLang grammar."""

    def __init__(self, tokens: list[Token], source_len: int) -> None:
        self.tokens = tokens
        self.source_len = source_len
        self.pos = 0

    def peek(self) -> Token | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def current_position(self) -> int:
        tok = self.peek()
        if tok is not None:
            return tok.position
        return self.source_len

    def consume(self) -> Token:
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", position=self.source_len)
        self.pos += 1
        return tok

    def is_at_end(self) -> bool:
        return self.pos >= len(self.tokens)

    def parse(self) -> Any:
        return self.or_expr()

    def or_expr(self) -> Any:
        node = self.and_expr()
        while self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().value == "or":
            op_tok = self.consume()
            right = self.and_expr()
            node = BinaryOp(op="or", left=node, right=right, position=op_tok.position)
        return node

    def and_expr(self) -> Any:
        node = self.not_expr()
        while self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().value == "and":
            op_tok = self.consume()
            right = self.not_expr()
            node = BinaryOp(op="and", left=node, right=right, position=op_tok.position)
        return node

    def not_expr(self) -> Any:
        if self.peek() is not None and self.peek().kind == "KEYWORD" and self.peek().value == "not":
            op_tok = self.consume()
            operand = self.not_expr()
            return UnaryOp(op="not", operand=operand, position=op_tok.position)
        return self.comparison()

    def comparison(self) -> Any:
        node = self.additive()
        comp_ops = ("==", "!=", "<", "<=", ">", ">=")
        if self.peek() is not None and self.peek().kind == "OP" and self.peek().value in comp_ops:
            op_tok = self.consume()
            right = self.additive()
            if self.peek() is not None and self.peek().kind == "OP" and self.peek().value in comp_ops:
                offending = self.peek()
                raise ParseError(
                    f"comparison operator '{offending.value}' is non-associative",
                    position=offending.position,
                )
            node = BinaryOp(op=op_tok.value, left=node, right=right, position=op_tok.position)
        return node

    def additive(self) -> Any:
        node = self.multiplicative()
        while self.peek() is not None and self.peek().kind == "OP" and self.peek().value in ("+", "-"):
            op_tok = self.consume()
            right = self.multiplicative()
            node = BinaryOp(op=op_tok.value, left=node, right=right, position=op_tok.position)
        return node

    def multiplicative(self) -> Any:
        node = self.unary()
        while self.peek() is not None and self.peek().kind == "OP" and self.peek().value in ("*", "/", "%"):
            op_tok = self.consume()
            right = self.unary()
            node = BinaryOp(op=op_tok.value, left=node, right=right, position=op_tok.position)
        return node

    def unary(self) -> Any:
        if self.peek() is not None and self.peek().kind == "OP" and self.peek().value == "-":
            op_tok = self.consume()
            operand = self.unary()
            return UnaryOp(op="-", operand=operand, position=op_tok.position)
        return self.power()

    def power(self) -> Any:
        node = self.primary()
        if self.peek() is not None and self.peek().kind == "OP" and self.peek().value == "^":
            op_tok = self.consume()
            right = self.unary()
            node = BinaryOp(op="^", left=node, right=right, position=op_tok.position)
        return node

    def primary(self) -> Any:
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", position=self.source_len)

        if tok.kind == "NUMBER":
            self.consume()
            return Literal(value=tok.value, position=tok.position)

        if tok.kind == "STRING":
            self.consume()
            return Literal(value=tok.value, position=tok.position)

        if tok.kind == "KEYWORD":
            if tok.value == "true":
                self.consume()
                return Literal(value=True, position=tok.position)
            elif tok.value == "false":
                self.consume()
                return Literal(value=False, position=tok.position)
            else:
                raise ParseError(f"unexpected keyword '{tok.value}'", position=tok.position)

        if tok.kind == "IDENT":
            ident_tok = self.consume()
            if self.peek() is not None and self.peek().kind == "OP" and self.peek().value == "(":
                self.consume()  # consume '('
                args: list[Any] = []
                if self.peek() is not None and not (self.peek().kind == "OP" and self.peek().value == ")"):
                    args.append(self.or_expr())
                    while self.peek() is not None and self.peek().kind == "OP" and self.peek().value == ",":
                        self.consume()  # consume ','
                        args.append(self.or_expr())
                if self.peek() is None or not (self.peek().kind == "OP" and self.peek().value == ")"):
                    raise ParseError("expected ')' after function arguments", position=self.current_position())
                self.consume()  # consume ')'
                return FunctionCall(name=ident_tok.value, args=args, position=ident_tok.position)
            return Variable(name=ident_tok.value, position=ident_tok.position)

        if tok.kind == "OP" and tok.value == "(":
            self.consume()
            expr_node = self.or_expr()
            if self.peek() is None or not (self.peek().kind == "OP" and self.peek().value == ")"):
                raise ParseError("expected ')'", position=self.current_position())
            self.consume()
            return expr_node

        raise ParseError(f"unexpected token '{tok.value}'", position=tok.position)


def parse(source: str) -> object:
    """Parse source string into an AST root node."""
    tokens = tokenize(source)
    if not tokens:
        raise ParseError("empty source", position=0)
    parser = Parser(tokens, len(source))
    ast = parser.parse()
    if not parser.is_at_end():
        trailing = parser.peek()
        raise ParseError(f"unexpected trailing token: {trailing.value!r}", position=trailing.position)
    return ast

"""MiniLang built-in functions."""

import math
from typing import Any
from .errors import EvalError


def format_number(val: float) -> str:
    """Format a float according to MiniLang rules (rule 33)."""
    if val.is_integer():
        return str(int(val))
    return repr(val)


def builtin_abs(args: list[Any], position: int | None = None) -> float:
    if len(args) != 1:
        raise EvalError(f"abs() takes 1 argument(s), got {len(args)}", position=position)
    x = args[0]
    if type(x) is not float:
        raise EvalError(f"abs() argument must be a number, got {type(x).__name__}", position=position)
    return float(abs(x))


def builtin_min(args: list[Any], position: int | None = None) -> float:
    if len(args) < 1:
        raise EvalError(f"min() takes at least 1 argument(s), got {len(args)}", position=position)
    for arg in args:
        if type(arg) is not float:
            raise EvalError(f"min() arguments must be numbers, got {type(arg).__name__}", position=position)
    return float(min(args))


def builtin_max(args: list[Any], position: int | None = None) -> float:
    if len(args) < 1:
        raise EvalError(f"max() takes at least 1 argument(s), got {len(args)}", position=position)
    for arg in args:
        if type(arg) is not float:
            raise EvalError(f"max() arguments must be numbers, got {type(arg).__name__}", position=position)
    return float(max(args))


def builtin_round(args: list[Any], position: int | None = None) -> float:
    if len(args) not in (1, 2):
        raise EvalError(f"round() takes 1 or 2 argument(s), got {len(args)}", position=position)
    x = args[0]
    if type(x) is not float:
        raise EvalError(f"round() first argument must be a number, got {type(x).__name__}", position=position)
    if len(args) == 1:
        return float(round(x))
    n = args[1]
    if type(n) is not float or not n.is_integer():
        raise EvalError("round() second argument must be a whole number", position=position)
    return float(round(x, int(n)))


def builtin_len(args: list[Any], position: int | None = None) -> float:
    if len(args) != 1:
        raise EvalError(f"len() takes 1 argument(s), got {len(args)}", position=position)
    s = args[0]
    if type(s) is not str:
        raise EvalError(f"len() argument must be a string, got {type(s).__name__}", position=position)
    return float(len(s))


def builtin_upper(args: list[Any], position: int | None = None) -> str:
    if len(args) != 1:
        raise EvalError(f"upper() takes 1 argument(s), got {len(args)}", position=position)
    s = args[0]
    if type(s) is not str:
        raise EvalError(f"upper() argument must be a string, got {type(s).__name__}", position=position)
    return s.upper()


def builtin_lower(args: list[Any], position: int | None = None) -> str:
    if len(args) != 1:
        raise EvalError(f"lower() takes 1 argument(s), got {len(args)}", position=position)
    s = args[0]
    if type(s) is not str:
        raise EvalError(f"lower() argument must be a string, got {type(s).__name__}", position=position)
    return s.lower()


def builtin_str(args: list[Any], position: int | None = None) -> str:
    if len(args) != 1:
        raise EvalError(f"str() takes 1 argument(s), got {len(args)}", position=position)
    x = args[0]
    if type(x) is bool:
        return "true" if x else "false"
    elif type(x) is float:
        return format_number(x)
    elif type(x) is str:
        return x
    else:
        raise EvalError(f"unsupported value for str(): {x!r}", position=position)


def builtin_num(args: list[Any], position: int | None = None) -> float:
    if len(args) != 1:
        raise EvalError(f"num() takes 1 argument(s), got {len(args)}", position=position)
    s = args[0]
    if type(s) is not str:
        raise EvalError(f"num() argument must be a string, got {type(s).__name__}", position=position)
    try:
        val = float(s)
        if math.isnan(val) or math.isinf(val):
            raise ValueError()
        return val
    except ValueError:
        raise EvalError(f"cannot convert {s!r} to number", position=position)


EAGER_BUILTINS = {
    "abs": builtin_abs,
    "min": builtin_min,
    "max": builtin_max,
    "round": builtin_round,
    "len": builtin_len,
    "upper": builtin_upper,
    "lower": builtin_lower,
    "str": builtin_str,
    "num": builtin_num,
}

ALL_BUILTINS = set(EAGER_BUILTINS.keys()) | {"if"}

"""MiniLang evaluator."""

from typing import Any
from .errors import EvalError
from .parser import BinaryOp, FunctionCall, Literal, UnaryOp, Variable, parse
from .builtins import ALL_BUILTINS, EAGER_BUILTINS


def evaluate_ast(node: Any, env: dict[str, Any]) -> Any:
    """Evaluate an AST node within the given environment."""
    if isinstance(node, Literal):
        return node.value

    if isinstance(node, Variable):
        if node.name not in env:
            raise EvalError(f"undefined variable: {node.name}", position=node.position)
        val = env[node.name]
        # Rule 26: env values must be float, str or bool. int values are not accepted.
        if type(val) not in (float, str, bool):
            raise EvalError(f"unsupported value for {node.name}: {val!r}", position=node.position)
        return val

    if isinstance(node, FunctionCall):
        name = node.name
        if name not in ALL_BUILTINS:
            raise EvalError(f"undefined function: {name}", position=node.position)
        if name == "if":
            if len(node.args) != 3:
                raise EvalError(f"if() takes 3 argument(s), got {len(node.args)}", position=node.position)
            cond = evaluate_ast(node.args[0], env)
            if type(cond) is not bool:
                raise EvalError("if() condition must be a boolean", position=node.position)
            if cond:
                return evaluate_ast(node.args[1], env)
            else:
                return evaluate_ast(node.args[2], env)

        # Eager evaluation of arguments for standard built-ins
        args = [evaluate_ast(arg, env) for arg in node.args]
        return EAGER_BUILTINS[name](args, position=node.position)

    if isinstance(node, UnaryOp):
        if node.op == "not":
            val = evaluate_ast(node.operand, env)
            if type(val) is not bool:
                raise EvalError("'not' requires a boolean", position=node.position)
            return not val
        elif node.op == "-":
            val = evaluate_ast(node.operand, env)
            if type(val) is not float:
                raise EvalError("unary '-' requires a number", position=node.position)
            return -val
        else:
            raise EvalError(f"unknown unary operator: {node.op}", position=node.position)

    if isinstance(node, BinaryOp):
        op = node.op
        # Short-circuit logical operators
        if op == "and":
            left = evaluate_ast(node.left, env)
            if type(left) is not bool:
                raise EvalError("left operand of 'and' must be a boolean", position=node.position)
            if not left:
                return False
            right = evaluate_ast(node.right, env)
            if type(right) is not bool:
                raise EvalError("right operand of 'and' must be a boolean", position=node.position)
            return right

        if op == "or":
            left = evaluate_ast(node.left, env)
            if type(left) is not bool:
                raise EvalError("left operand of 'or' must be a boolean", position=node.position)
            if left:
                return True
            right = evaluate_ast(node.right, env)
            if type(right) is not bool:
                raise EvalError("right operand of 'or' must be a boolean", position=node.position)
            return right

        # Standard binary operators
        left = evaluate_ast(node.left, env)
        right = evaluate_ast(node.right, env)

        if op == "+":
            if type(left) is float and type(right) is float:
                return left + right
            if type(left) is str and type(right) is str:
                return left + right
            raise EvalError(
                f"'+' requires two numbers or two strings, got {type(left).__name__} and {type(right).__name__}",
                position=node.position,
            )

        if op in ("-", "*", "/", "%", "^"):
            if type(left) is not float or type(right) is not float:
                raise EvalError(
                    f"'{op}' requires numbers, got {type(left).__name__} and {type(right).__name__}",
                    position=node.position,
                )
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if op == "/":
                if right == 0.0:
                    raise EvalError("division by zero", position=node.position)
                return left / right
            if op == "%":
                if right == 0.0:
                    raise EvalError("modulo by zero", position=node.position)
                return left % right
            if op == "^":
                if left == 0.0 and right < 0.0:
                    raise EvalError("division by zero", position=node.position)
                try:
                    res = left ** right
                except ZeroDivisionError:
                    raise EvalError("division by zero", position=node.position)
                except Exception as e:
                    raise EvalError(str(e), position=node.position)
                if isinstance(res, complex):
                    if res.imag != 0:
                        raise EvalError("result of ^ is not a real number", position=node.position)
                    res = res.real
                return float(res)

        if op == "==":
            if type(left) is not type(right):
                return False
            return left == right

        if op == "!=":
            if type(left) is not type(right):
                return True
            return left != right

        if op in ("<", "<=", ">", ">="):
            if (type(left) is float and type(right) is float) or (type(left) is str and type(right) is str):
                if op == "<":
                    return left < right
                if op == "<=":
                    return left <= right
                if op == ">":
                    return left > right
                if op == ">=":
                    return left >= right
            raise EvalError(
                f"'{op}' requires two numbers or two strings, got {type(left).__name__} and {type(right).__name__}",
                position=node.position,
            )

        raise EvalError(f"unknown binary operator: {op}", position=node.position)

    raise EvalError(f"unknown AST node type: {type(node).__name__}")


def evaluate(source: str, env: dict[str, Any] | None = None) -> object:
    """Evaluate source expression within the given environment."""
    ast = parse(source)
    env_mapping = env if env is not None else {}
    return evaluate_ast(ast, env_mapping)

"""MiniLang REPL."""

import re
import sys
from .errors import MiniLangError
from .evaluator import evaluate

ASSIGN_RE = re.compile(r"^\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)\s*(.*)$")
KEYWORDS = {"true", "false", "and", "or", "not"}


def format_repl_string(s: str) -> str:
    """Format a string with double quotes and re-escaped contents."""
    out: list[str] = []
    for ch in s:
        if ch == "\\":
            out.append("\\\\")
        elif ch == '"':
            out.append('\\"')
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        else:
            out.append(ch)
    return '"' + "".join(out) + '"'


def format_repl_value(val: object) -> str:
    """Format any MiniLang value for REPL output."""
    if type(val) is bool:
        return "true" if val else "false"
    elif type(val) is float:
        if val.is_integer():
            return str(int(val))
        return repr(val)
    elif type(val) is str:
        return format_repl_string(val)
    else:
        return repr(val)


def main() -> None:
    env: dict[str, object] = {}
    for line in sys.stdin:
        line = line.rstrip("\r\n")
        stripped = line.strip()
        if not stripped:
            continue
        if stripped == ":quit":
            sys.exit(0)
        if stripped == ":vars":
            for k in sorted(env.keys()):
                print(f"{k} = {format_repl_value(env[k])}")
            continue

        # Check variable assignment
        m = ASSIGN_RE.match(line)
        if m and m.group(1) not in KEYWORDS:
            ident = m.group(1)
            expr_str = m.group(2)
            try:
                val = evaluate(expr_str, env)
                env[ident] = val
            except MiniLangError as e:
                print(f"error: {e}")
            continue

        # Evaluate expression
        try:
            val = evaluate(line, env)
            print(format_repl_value(val))
